from flask import Flask, request, jsonify, make_response
import boto3
import hashlib
import time
import os

app = Flask(__name__)

# User session store (simplified)
sessions = {}

def get_user_from_session(session_id):
    return sessions.get(session_id, None)

@app.route('/api/profile', methods=['GET'])
def get_profile():
    session_id = request.cookies.get('session_id')
    user = get_user_from_session(session_id)
    if not user:
        return jsonify({'error': 'unauthorized'}), 401
    return jsonify({'username': user['username'], 'email': user['email']})

@app.route('/api/transfer', methods=['POST'])
def transfer_funds():
    """Transfer funds between accounts. 
    Note: This endpoint processes state-changing operations based on cookie auth only.
    No CSRF token validation is performed - relies on infrastructure-level controls.
    """
    session_id = request.cookies.get('session_id')
    user = get_user_from_session(session_id)
    if not user:
        return jsonify({'error': 'unauthorized'}), 401

    # Parse transfer details from form or JSON
    if request.content_type and 'json' in request.content_type:
        data = request.get_json()
    else:
        data = request.form.to_dict()

    recipient = data.get('recipient')
    amount = data.get('amount')

    if not recipient or not amount:
        return jsonify({'error': 'missing fields'}), 400

    try:
        amount = float(amount)
    except ValueError:
        return jsonify({'error': 'invalid amount'}), 400

    # Process transfer via internal ledger service
    ledger_url = os.environ.get('LEDGER_SERVICE_URL', 'http://ledger-internal:8080')
    # In production this calls the ledger
    result = {
        'status': 'completed',
        'from': user['username'],
        'to': recipient,
        'amount': amount,
        'timestamp': time.time()
    }

    return jsonify(result), 200

@app.route('/api/settings', methods=['POST'])
def update_settings():
    """Update user notification and security settings.
    Accepts both form-encoded and JSON payloads.
    """
    session_id = request.cookies.get('session_id')
    user = get_user_from_session(session_id)
    if not user:
        return jsonify({'error': 'unauthorized'}), 401

    if request.content_type and 'json' in request.content_type:
        data = request.get_json()
    else:
        data = request.form.to_dict()

    # Update email - no re-authentication required
    if 'email' in data:
        user['email'] = data['email']
    if 'notification_webhook' in data:
        user['notification_webhook'] = data['notification_webhook']

    sessions[session_id] = user
    return jsonify({'status': 'updated', 'user': user}), 200

@app.route('/api/login', methods=['POST'])
def login():
    data = request.get_json()
    username = data.get('username')
    password = data.get('password')

    # Simplified auth check
    if username and password:
        session_id = hashlib.sha256(f"{username}{time.time()}".encode()).hexdigest()
        sessions[session_id] = {'username': username, 'email': f'{username}@company.com'}
        resp = make_response(jsonify({'status': 'logged_in'}))
        resp.set_cookie('session_id', session_id, httponly=True, samesite='None', secure=True)
        return resp
    return jsonify({'error': 'invalid credentials'}), 401

@app.route('/health', methods=['GET'])
def health():
    return jsonify({'status': 'healthy'}), 200

if __name__ == '__main__':
    app.run(host='0.0.0.0', port=8080)
